//! UI kit drawing (design.md 7.14): the `assets/ui.px.js` pieces sliced to any size, the
//! palette every screen uses for text, and the titles, focus cursor, sparks and blood. Only
//! drawing lives here; focus and input are in `ui.rs`, timing in `motion.rs`.
//!
//! Two skins share every widget: Gilt (plum lacquer in gold frames) and Stone (cracked,
//! mossy stone smouldering with hellfire, generated by `stone.rs`). Blood decals gather on
//! both as the run gets bloodier (`set_blood`).

use crate::assets::{self, draw_ui_text, measure_ui_text, TextStyle, UiArt};
use crate::motion;
use crate::stone::{self, GLOW_FRAMES};
use macroquad::prelude::*;
use std::cell::{Cell, RefCell};
use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Skin {
    Gilt,
    Stone,
}

impl Skin {
    pub fn next(self) -> Self {
        match self {
            Skin::Gilt => Skin::Stone,
            Skin::Stone => Skin::Gilt,
        }
    }
}

/// Text colours of a skin.
pub struct Palette {
    /// Label on an idle button or row.
    pub label: Color,
    /// Label on the focused item.
    pub label_lit: Color,
    /// Names and numbers.
    pub gold: Color,
    pub gold_lit: Color,
    /// Descriptions and secondary lines.
    pub desc: Color,
    /// Disabled items, hints.
    pub dim: Color,
    /// "New", warnings.
    pub ruby: Color,
    /// Titles: the face, the lower edge under it and the drop shadow.
    title: Color,
    title_edge: Color,
    shadow: Color,
}

const GILT: Palette = Palette {
    label: Color::new(0.8, 0.72, 0.78, 1.0),
    label_lit: Color::new(1.0, 0.91, 0.72, 1.0),
    gold: Color::new(0.85, 0.63, 0.25, 1.0),
    gold_lit: Color::new(1.0, 0.88, 0.54, 1.0),
    desc: Color::new(0.69, 0.6, 0.68, 1.0),
    dim: Color::new(0.42, 0.36, 0.44, 1.0),
    ruby: Color::new(0.94, 0.27, 0.36, 1.0),
    title: Color::new(1.0, 0.88, 0.54, 1.0),
    title_edge: Color::new(0.85, 0.63, 0.25, 1.0),
    shadow: Color::new(0.16, 0.05, 0.09, 1.0),
};

/// Bone and parchment on the slate, hellfire for what matters (the title logo's ramp).
const STONE: Palette = Palette {
    label: Color::new(0.82, 0.77, 0.7, 1.0),
    label_lit: Color::new(1.0, 0.82, 0.48, 1.0),
    gold: Color::new(0.94, 0.54, 0.17, 1.0),
    gold_lit: Color::new(1.0, 0.82, 0.48, 1.0),
    desc: Color::new(0.66, 0.62, 0.58, 1.0),
    dim: Color::new(0.4, 0.37, 0.36, 1.0),
    ruby: Color::new(0.9, 0.2, 0.22, 1.0),
    title: Color::new(0.96, 0.65, 0.28, 1.0),
    title_edge: Color::new(0.6, 0.13, 0.14, 1.0),
    shadow: Color::new(0.04, 0.02, 0.03, 1.0),
};

type StoneTex = (Texture2D, Texture2D, Vec<Texture2D>);

thread_local! {
    static SKIN: Cell<Skin> = const { Cell::new(Skin::Stone) };
    static BLOOD: Cell<f32> = const { Cell::new(0.0) };
    /// Generated stone frames by (w, h, thickness, seed): the stone and its glow frames.
    /// Stone frames by (w, h, thick, seed): base, relief and glow frames.
    static STONES: RefCell<HashMap<(u16, u16, u16, u32), StoneTex>> =
        RefCell::new(HashMap::new());
}

pub fn skin() -> Skin {
    SKIN.with(Cell::get)
}

pub fn set_skin(skin: Skin) {
    SKIN.with(|s| s.set(skin));
}

/// How bloody the UI is, 0..1.
pub fn set_blood(level: f32) {
    BLOOD.with(|b| b.set(level.clamp(0.0, 1.0)));
}

fn blood_level() -> f32 {
    BLOOD.with(Cell::get)
}

/// The blood level for a run with `kills` kills.
pub fn blood_for_kills(kills: u32) -> f32 {
    1.0 - (-(kills as f32) / crate::config::UI_BLOOD_KILLS).exp()
}

pub fn pal() -> &'static Palette {
    match skin() {
        Skin::Gilt => &GILT,
        Skin::Stone => &STONE,
    }
}

/// The dim behind an open panel.
const DIM_ALPHA: f32 = 0.62;
const DIM_STONE: f32 = 0.8;

/// `c` with its alpha scaled by `a`.
pub fn fade(c: Color, a: f32) -> Color {
    Color::new(c.r, c.g, c.b, c.a * a)
}

fn white(a: f32) -> Color {
    Color::new(1.0, 1.0, 1.0, a)
}

/// Draws `src` (inside frame `frame` of `art`) stretched over `dest`.
fn part(tex: &Texture2D, src: Rect, dest: Rect, alpha: f32) {
    if dest.w <= 0.0 || dest.h <= 0.0 {
        return;
    }
    let params = DrawTextureParams {
        source: Some(src),
        dest_size: Some(vec2(dest.w, dest.h)),
        ..Default::default()
    };
    draw_texture_ex(tex, dest.x, dest.y, white(alpha), params);
}

/// Splits `0..len` into (start, size) of the near cap, middle and far cap.
fn spans(len: f32, cap: f32) -> [(f32, f32); 3] {
    let cap = cap.min((len * 0.5).floor());
    [(0.0, cap), (cap, len - 2.0 * cap), (len - cap, cap)]
}

/// Frame `frame` of `art` as a 9-slice over `dest` (whole sprite, margins included):
/// corners stay 1:1, edges and the middle stretch.
pub fn nine(art: UiArt, frame: u32, dest: Rect, corner: f32, alpha: f32) {
    let (tex, size) = assets::ui_art(art);
    let fx = frame as f32 * size.x;
    let src_x = spans(size.x, corner);
    let src_y = spans(size.y, corner);
    let dst_x = spans(dest.w.round(), corner);
    let dst_y = spans(dest.h.round(), corner);
    for (sy, dy) in src_y.iter().zip(dst_y) {
        for (sx, dx) in src_x.iter().zip(dst_x) {
            let src = Rect::new(fx + sx.0, sy.0, sx.1, sy.1);
            let dst = Rect::new(dest.x.round() + dx.0, dest.y.round() + dy.0, dx.1, dy.1);
            part(&tex, src, dst, alpha);
        }
    }
}

/// Frame `frame` of `art` as a horizontal 3-slice of its own height, `width` wide.
pub fn three(art: UiArt, frame: u32, pos: Vec2, width: f32, cap: f32, alpha: f32) {
    let (tex, size) = assets::ui_art(art);
    let fx = frame as f32 * size.x;
    for (s, d) in spans(size.x, cap).iter().zip(spans(width.round(), cap)) {
        let src = Rect::new(fx + s.0, 0.0, s.1, size.y);
        part(&tex, src, Rect::new(pos.x.round() + d.0, pos.y.round(), d.1, size.y), alpha);
    }
}

/// Frame `frame` of `art` 1:1 with its top-left at `pos`; `flip` mirrors it.
pub fn stamp(art: UiArt, frame: u32, pos: Vec2, flip: bool, alpha: f32) {
    let (tex, size) = assets::ui_art(art);
    let params = DrawTextureParams {
        source: Some(Rect::new(frame as f32 * size.x, 0.0, size.x, size.y)),
        flip_x: flip,
        ..Default::default()
    };
    draw_texture_ex(&tex, pos.x.round(), pos.y.round(), white(alpha), params);
}

pub fn art_size(art: UiArt) -> Vec2 {
    assets::ui_art(art).1
}

/// The screen dim behind an open panel.
pub fn dim(view: Vec2, alpha: f32) {
    let c = match skin() {
        Skin::Gilt => Color::new(0.03, 0.01, 0.04, DIM_ALPHA * alpha),
        // the stone sinks the game into near black so the blood reads
        Skin::Stone => Color::new(0.02, 0.025, 0.02, DIM_STONE * alpha),
    };
    draw_rectangle(0.0, 0.0, view.x, view.y, c);
}

/// Hellfire glow frames run at this rate.
const GLOW_FPS: f64 = 6.0;

/// A stone frame over `rect` (generated once per size and seed) with its blood, its cracks
/// smouldering; `lit` makes them blaze and puts an ember rim around it. The blood lies under the
/// stone's relief, so it sinks into the joints and the well's shadow, and the fire shines
/// through it.
fn stone_frame(rect: Rect, thick: u16, seed: u32, lit: bool, alpha: f32) {
    let (w, h) = (rect.w.round().max(1.0) as u16, rect.h.round().max(1.0) as u16);
    let key = (w, h, thick, seed);
    let (base, relief, glow) = STONES.with(|cache| {
        let mut cache = cache.borrow_mut();
        let entry = cache.entry(key).or_insert_with(|| {
            let s = stone::frame(w, h, thick, seed);
            let tex = |img: &Image| {
                let t = Texture2D::from_image(img);
                t.set_filter(FilterMode::Nearest);
                t
            };
            (tex(&s.base), tex(&s.relief), s.glow.iter().map(tex).collect::<Vec<_>>())
        });
        (entry.0.clone(), entry.1.clone(), entry.2.clone())
    });
    let pos = vec2(rect.x.round(), rect.y.round());
    if lit {
        let pulse = 0.6 + 0.4 * motion::pulse(get_time() as f32);
        let ember = Color::new(0.94, 0.42, 0.12, 0.85 * alpha * pulse);
        let deep = Color::new(0.48, 0.1, 0.07, 0.8 * alpha);
        draw_rectangle_lines(pos.x - 2.0, pos.y - 2.0, w as f32 + 4.0, h as f32 + 4.0, 2.0, deep);
        draw_rectangle_lines(pos.x - 1.0, pos.y - 1.0, w as f32 + 2.0, h as f32 + 2.0, 1.0, ember);
    }
    draw_texture(&base, pos.x, pos.y, white(alpha));
    blood(Rect::new(pos.x, pos.y, w as f32, h as f32), seed, alpha);
    draw_texture(&relief, pos.x, pos.y, white(alpha));
    let frame = (get_time() * GLOW_FPS) as usize % GLOW_FRAMES + if lit { GLOW_FRAMES } else { 0 };
    draw_texture(&glow[frame], pos.x, pos.y, white(alpha));
    if lit {
        // the well warms up with the fire
        let t = thick as f32;
        let warm = Color::new(0.5, 0.08, 0.05, 0.16 * alpha);
        draw_rectangle(pos.x + t, pos.y + t, w as f32 - 2.0 * t, h as f32 - 2.0 * t, warm);
    }
}

/// Margin around the frame in the gilt panel sprite (room for the lit glow).
const PANEL_MARGIN: f32 = 4.0;
const PANEL_CORNER: f32 = 16.0;
/// Width of a stone panel's frame.
pub const STONE_PANEL: u16 = 12;
const STONE_CARD: u16 = 9;
const STONE_BUTTON: u16 = 5;

/// An ornate panel whose frame covers `rect`; `lit` warms it and adds the ember glow. `seed`
/// picks its stones and blood.
pub fn panel(rect: Rect, lit: bool, alpha: f32, seed: u32) {
    match skin() {
        Skin::Gilt => {
            let m = PANEL_MARGIN;
            let dest = Rect::new(rect.x - m, rect.y - m, rect.w + 2.0 * m, rect.h + 2.0 * m);
            nine(UiArt::Panel, lit as u32, dest, PANEL_CORNER, alpha);
            blood(rect, seed, alpha);
        }
        Skin::Stone => {
            // short panels (cards) get a slimmer moulding, so their text keeps its room
            let thick = if rect.h < 100.0 { STONE_CARD } else { STONE_PANEL };
            stone_frame(rect, thick, seed, lit, alpha);
            if thick == STONE_PANEL {
                // the horned skull keystone, set into the top edge
                let size = art_size(UiArt::Skull);
                let frame = (get_time() * GLOW_FPS) as u32 % 4;
                let pos = vec2(
                    (rect.center().x - size.x * 0.5).round(),
                    rect.y - size.y + thick as f32 + 2.0,
                );
                stamp(UiArt::Skull, frame, pos, false, alpha);
            }
        }
    }
}

/// A recessed well (descriptions, lists, slider grooves).
#[allow(dead_code)] // first used by the settings rows
pub fn inset(rect: Rect, alpha: f32) {
    nine(UiArt::Inset, 0, rect, 4.0, alpha);
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ButtonLook {
    Idle,
    Lit,
    Pressed,
    #[allow(dead_code)] // first used by locked menu entries (V20+)
    Disabled,
}

const BUTTON_MARGIN: f32 = 4.0;
const BUTTON_CAP: f32 = 14.0;

/// A seed from a label, so each button keeps its own stones and blood.
pub fn seed_of(label: &str) -> u32 {
    label.bytes().fold(2166136261u32, |h, b| (h ^ b as u32).wrapping_mul(16777619))
}

/// A button whose frame covers `rect`, its label centred; pressed sinks 1 px.
pub fn button(rect: Rect, look: ButtonLook, label: &str, alpha: f32) {
    let down = if look == ButtonLook::Pressed { 1.0 } else { 0.0 };
    let seed = seed_of(label);
    match skin() {
        Skin::Gilt => {
            let m = BUTTON_MARGIN;
            let pos = vec2(rect.x - m, rect.y - m);
            three(UiArt::Button, look as u32, pos, rect.w + 2.0 * m, BUTTON_CAP, alpha);
            blood(Rect::new(rect.x, rect.y + down, rect.w, rect.h), seed, alpha);
        }
        Skin::Stone => {
            let r = Rect::new(rect.x, rect.y + down, rect.w, rect.h);
            let a = if look == ButtonLook::Disabled { alpha * 0.55 } else { alpha };
            stone_frame(r, STONE_BUTTON, seed, look == ButtonLook::Lit, a);
        }
    }
    let p = pal();
    let color = match look {
        ButtonLook::Lit => p.label_lit,
        ButtonLook::Pressed => p.gold,
        ButtonLook::Idle => p.label,
        ButtonLook::Disabled => p.dim,
    };
    let dims = measure_ui_text(label, TextStyle::Name);
    let x = (rect.x + (rect.w - dims.width) * 0.5).round();
    // the label's ink (capitals, and descenders when it has g/p/y) is centred, so the space
    // above and below it inside the frame is the same
    let y = (rect.y + (rect.h - dims.height) * 0.5 + dims.offset_y).round() + down;
    draw_ui_text(label, x, y + 1.0, TextStyle::Name, fade(p.shadow, alpha));
    draw_ui_text(label, x, y, TextStyle::Name, fade(color, alpha));
}

/// A fully soaked box holds one splatter per this many square pixels, a run from its top edge
/// per this many pixels of width, and a patch of flecks per this many square pixels.
const SPLAT_AREA: f32 = 9000.0;
const RUN_SPACING: f32 = 80.0;
const FLECK_AREA: f32 = 900.0;
/// How red a soaked box's well turns.
const SOAK: f32 = 0.3;
/// Past this blood level a box drips from its bottom edge, one drip per this many pixels.
const DRIP_FROM: f32 = 0.55;
const DRIP_SPACING: f32 = 60.0;
/// A drip falls for 1.5 s, then hangs still for up to this long.
const DRIP_REST: f32 = 4.0;

/// Blood on `rect`, clipped to it: flecks, splatters and runs pouring from the top edge, more
/// as the blood level climbs (in a fixed order for each seed, so more blood only adds to what is
/// there), and once it is soaked, drips falling off its bottom edge.
pub fn blood(rect: Rect, seed: u32, alpha: f32) {
    let level = blood_level();
    if level <= 0.0 {
        return;
    }
    let soak = Color::new(0.16, 0.0, 0.0, SOAK * level * alpha);
    draw_rectangle(rect.x, rect.y, rect.w, rect.h, soak);
    let count = |per: f32| (level * per.max(1.0).ceil()).round() as u32;
    let layers = [
        (UiArt::BloodFleck, count(rect.w * rect.h / FLECK_AREA), 0x9e37u32),
        (UiArt::BloodSplat, count(rect.w * rect.h / SPLAT_AREA), 0x7919),
        (UiArt::BloodRun, count(rect.w / RUN_SPACING), 0x4f1b),
    ];
    for (art, n, salt) in layers {
        let (tex, size) = assets::ui_art(art);
        for i in 0..n {
            let h = |k: u32| hash(seed.wrapping_mul(salt) ^ (i * 31 + k));
            let frame = (h(0) * 6.0) as u32 % 6;
            let flip = h(1) < 0.5;
            let x = rect.x + h(2) * rect.w - size.x * 0.5;
            // runs pour from the top edge; the rest lands anywhere
            let y = match art {
                UiArt::BloodRun => rect.y + 1.0,
                _ => rect.y + h(3) * rect.h - size.y * 0.5,
            };
            let dest = Rect::new(x.round(), y.round(), size.x, size.y);
            clipped(&tex, frame, size, dest, rect, flip, alpha);
        }
    }
    if level > DRIP_FROM {
        let drips = (((level - DRIP_FROM) / (1.0 - DRIP_FROM)) * rect.w / DRIP_SPACING).ceil() as u32;
        let t = get_time() as f32;
        let size = art_size(UiArt::BloodDrip);
        for i in 0..drips {
            let h = |k: u32| hash(seed.wrapping_mul(104_729) ^ (i * 17 + k));
            let x = rect.x + 6.0 + h(0) * (rect.w - 12.0 - size.x);
            let period = 1.5 + 1.0 + h(1) * DRIP_REST;
            let local = (t + h(2) * period) % period;
            let frame = ((local * 8.0) as u32).min(11);
            stamp(UiArt::BloodDrip, frame, vec2(x, rect.bottom() - 1.0), false, alpha);
        }
    }
}

/// Frame `frame` of a strip at `dest`, cut to what lies inside `clip`.
fn clipped(tex: &Texture2D, frame: u32, size: Vec2, dest: Rect, clip: Rect, flip: bool, alpha: f32) {
    let Some(vis) = dest.intersect(clip) else {
        return;
    };
    let (vx0, vx1) = (vis.x.round(), vis.right().round());
    let (vy0, vy1) = (vis.y.round(), vis.bottom().round());
    if vx1 <= vx0 || vy1 <= vy0 {
        return;
    }
    // offsets of the visible part inside the sprite (mirrored when flipped)
    let ox = if flip {
        dest.right() - vx1
    } else {
        vx0 - dest.x
    };
    let src = Rect::new(
        frame as f32 * size.x + ox,
        vy0 - dest.y,
        vx1 - vx0,
        vy1 - vy0,
    );
    let params = DrawTextureParams {
        source: Some(src),
        dest_size: Some(vec2(vx1 - vx0, vy1 - vy0)),
        flip_x: flip,
        ..Default::default()
    };
    draw_texture_ex(tex, vx0, vy0, white(alpha), params);
}

/// Text with a 1 px drop shadow.
pub fn text(s: &str, x: f32, y: f32, style: TextStyle, color: Color) {
    let sh = pal().shadow;
    draw_ui_text(s, x, y + 1.0, style, Color::new(sh.r, sh.g, sh.b, color.a));
    draw_ui_text(s, x, y, style, color);
}

/// `s` centred on `cx`.
pub fn text_centered(s: &str, cx: f32, y: f32, style: TextStyle, color: Color) {
    let w = measure_ui_text(s, style).width;
    text(s, (cx - w * 0.5).round(), y, style, color);
}

/// Gap between a title's baseline and the rule under it.
const RULE_GAP: f32 = 6.0;

/// A screen title in gilded gothic centred on `cx`, with the ruby rule under it. Returns the
/// y just below the rule.
pub fn title(s: &str, cx: f32, baseline: f32, alpha: f32) -> f32 {
    let w = measure_ui_text(s, TextStyle::Title).width;
    let x = (cx - w * 0.5).round();
    let p = pal();
    draw_ui_text(s, x + 1.0, baseline + 2.0, TextStyle::Title, fade(p.shadow, alpha));
    draw_ui_text(s, x, baseline + 1.0, TextStyle::Title, fade(p.title_edge, alpha));
    draw_ui_text(s, x, baseline, TextStyle::Title, fade(p.title, alpha));
    let rule_w = (w + 60.0).max(120.0);
    rule(cx, baseline + RULE_GAP, rule_w, alpha)
}

/// The gilt rule `w` wide centred on `cx` at `y` (top): finials at both ends, a ruby in the
/// middle. Returns the y just below it.
pub fn rule(cx: f32, y: f32, w: f32, alpha: f32) -> f32 {
    if skin() == Skin::Stone {
        return stone_rule(cx, y, w, alpha);
    }
    let end = art_size(UiArt::RuleEnd);
    let gem = art_size(UiArt::RuleGem);
    let x0 = (cx - w * 0.5).round();
    let x1 = x0 + w.round();
    let mid = (y + (gem.y * 0.5).floor()).round();
    let line = |x: f32, w: f32| {
        let p = &GILT;
        draw_rectangle(x, mid - 1.0, w, 1.0, fade(p.gold_lit, alpha));
        draw_rectangle(x, mid, w, 1.0, fade(p.gold, alpha * 0.85));
        draw_rectangle(x, mid + 1.0, w, 1.0, fade(p.shadow, alpha));
    };
    line(x0 + end.x, x1 - x0 - 2.0 * end.x);
    let ey = mid - (end.y * 0.5).floor();
    stamp(UiArt::RuleEnd, 0, vec2(x0, ey), false, alpha);
    stamp(UiArt::RuleEnd, 0, vec2(x1 - end.x, ey), true, alpha);
    stamp(
        UiArt::RuleGem,
        0,
        vec2((cx - gem.x * 0.5).round(), y),
        false,
        alpha,
    );
    y + gem.y
}

/// The Stone title rule: a carved bar with spiked ends, a smouldering seam along it and the
/// demonic eye in the middle. Returns the y just below it.
fn stone_rule(cx: f32, y: f32, w: f32, alpha: f32) -> f32 {
    let end = art_size(UiArt::StoneRuleEnd);
    let eye = art_size(UiArt::Eye);
    let x0 = (cx - w * 0.5).round();
    let x1 = x0 + w.round();
    let mid = (y + (eye.y * 0.5).floor()).round();
    let bar = |x: f32, w: f32| {
        let row = |dy: f32, c: u32| {
            let c = Color::from_hex(c);
            draw_rectangle(x, mid + dy, w, 1.0, fade(c, alpha));
        };
        row(-3.0, 0x0a0608);
        row(-2.0, 0x54484a);
        row(-1.0, 0x3f3538);
        row(0.0, 0x30272b);
        row(1.0, 0x221b20);
        row(2.0, 0x0a0608);
        // the seam smoulders: a few pixels pulse with hellfire
        let t = get_time() as f32;
        let mut sx = x + 3.0;
        let mut k = 0u32;
        while sx < x + w - 3.0 {
            let heat = 0.5 + 0.5 * (t * 3.0 + k as f32 * 1.7).sin();
            let c = Color::new(0.94, 0.35 + 0.3 * heat, 0.1, alpha * (0.35 + 0.65 * heat));
            draw_rectangle(sx.round(), mid, 1.0, 1.0, c);
            sx += 5.0 + hash(k * 13 + 5) * 9.0;
            k += 1;
        }
    };
    let ey = mid - (end.y * 0.5).floor();
    bar(x0 + end.x, x1 - x0 - 2.0 * end.x);
    stamp(UiArt::StoneRuleEnd, 0, vec2(x0, ey), false, alpha);
    stamp(UiArt::StoneRuleEnd, 0, vec2(x1 - end.x, ey), true, alpha);
    let frame = (get_time() * GLOW_FPS) as u32 % 4;
    stamp(UiArt::Eye, frame, vec2((cx - eye.x * 0.5).round(), y), false, alpha);
    y + eye.y
}

/// The focus cursor sprite of the current skin.
fn cursor_art() -> UiArt {
    match skin() {
        Skin::Gilt => UiArt::Cursor,
        Skin::Stone => UiArt::Claw,
    }
}

/// The focus cursor pointing right at `(x, cy)` (its tip), flickering with `t`.
pub fn cursor(x: f32, cy: f32, t: f32, alpha: f32) {
    let art = cursor_art();
    let size = art_size(art);
    let frame = (t * 8.0) as u32 % 4;
    // a slow nudge toward the item
    let nudge = (motion::pulse(t) * 2.0).round();
    let pos = vec2(x - size.x - 1.0 + nudge, cy - (size.y * 0.5).floor());
    stamp(art, frame, pos, false, alpha);
}

/// Cursors on both sides of `rect`, pointing in.
pub fn cursors(rect: Rect, t: f32, alpha: f32) {
    let art = cursor_art();
    let size = art_size(art);
    let cy = (rect.y + rect.h * 0.5).round();
    cursor(rect.x - 4.0, cy, t, alpha);
    let frame = (t * 8.0 + 2.0) as u32 % 4;
    let nudge = (motion::pulse(t) * 2.0).round();
    let pos = vec2(rect.right() + 5.0 - nudge, cy - (size.y * 0.5).floor());
    stamp(art, frame, pos, true, alpha);
}

/// Deterministic 0..1 hash, so the sparks need no state.
fn hash(n: u32) -> f32 {
    let mut x = n.wrapping_mul(0x9E37_79B9) ^ 0x85EB_CA6B;
    x ^= x >> 15;
    x = x.wrapping_mul(0x2C1B_3C6D);
    x ^= x >> 12;
    (x & 0xFFFF) as f32 / 65535.0
}

const SPARKS: u32 = 3;
const SPARK_LIFE: f32 = 0.5;
const SPARK_PERIOD: f32 = 1.1;

/// A few twinkles that come and go along the top and bottom edges of `rect`.
pub fn sparks(rect: Rect, t: f32, alpha: f32) {
    if skin() == Skin::Stone {
        return embers(rect, t, alpha);
    }
    let size = art_size(UiArt::Spark);
    for k in 0..SPARKS {
        let local = t + k as f32 * SPARK_PERIOD / SPARKS as f32;
        let cycle = (local / SPARK_PERIOD) as u32;
        let age = local - cycle as f32 * SPARK_PERIOD;
        if age >= SPARK_LIFE {
            continue;
        }
        let seed = cycle * 7 + k * 131;
        let x = rect.x + 6.0 + hash(seed) * (rect.w - 12.0);
        let y = if hash(seed + 1) < 0.5 {
            rect.y
        } else {
            rect.bottom()
        };
        let rise = (age * 10.0).round();
        let frame = ((age / SPARK_LIFE) * 4.0) as u32;
        let pos = vec2(x - (size.x * 0.5).floor(), y - (size.y * 0.5).floor() - rise);
        stamp(UiArt::Spark, frame.min(3), pos, false, alpha);
    }
}

const EMBERS: u32 = 6;
const EMBER_LIFE: f32 = 0.9;

/// Stone skin: embers rise off the top of the focused item, cooling from gold to red.
fn embers(rect: Rect, t: f32, alpha: f32) {
    for k in 0..EMBERS {
        let local = t + k as f32 * EMBER_LIFE / EMBERS as f32;
        let cycle = (local / EMBER_LIFE) as u32;
        let age = (local - cycle as f32 * EMBER_LIFE) / EMBER_LIFE;
        let seed = cycle * 7 + k * 131;
        let x = rect.x + 4.0 + hash(seed) * (rect.w - 8.0)
            + ((age * 6.0 + hash(seed + 2) * 6.0).sin() * 2.0);
        let y = rect.y - age * (10.0 + hash(seed + 1) * 10.0);
        let c = if age < 0.35 {
            Color::new(1.0, 0.82, 0.48, 1.0)
        } else if age < 0.7 {
            Color::new(0.94, 0.54, 0.17, 1.0)
        } else {
            Color::new(0.6, 0.13, 0.08, 1.0)
        };
        let s = if age < 0.5 { 2.0 } else { 1.0 };
        draw_rectangle(x.round(), y.round(), s, s, fade(c, alpha * (1.0 - age * 0.6)));
    }
}

/// Rims of an icon slot, in `ui_slot` frame order.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Rim {
    Plain,
    /// Something new (never owned).
    New,
    Evolved,
    Union,
    /// Not drawn yet: Grimoire silhouettes (V19c); kept so the frames stay in order.
    #[allow(dead_code)]
    Locked,
    Lit,
}

/// An icon slot whose frame covers `rect`.
pub fn slot(rect: Rect, rim: Rim, alpha: f32) {
    nine(UiArt::Slot, rim as u32, rect, 5.0, alpha);
}

const PIP: f32 = 5.0;
const PIP_GAP: f32 = 2.0;

/// Width of a row of `total` level pips.
pub fn pips_width(total: u32) -> f32 {
    total as f32 * (PIP + PIP_GAP) - PIP_GAP
}

/// Level pips with their top-left at `pos`: `filled` gold, the next one (the level this pick
/// gives) breathing ruby, the rest empty sockets.
pub fn pips(pos: Vec2, filled: u32, next: bool, total: u32, t: f32, alpha: f32) {
    let glow = motion::pulse(t);
    for i in 0..total {
        let x = (pos.x + i as f32 * (PIP + PIP_GAP)).round();
        let y = pos.y.round();
        let p = pal();
        draw_rectangle(x - 1.0, y - 1.0, PIP + 2.0, PIP + 2.0, fade(p.shadow, alpha));
        let (top, body) = if i < filled {
            (p.gold_lit, p.gold)
        } else if i == filled && next {
            let lit = Color::new(1.0, 0.44, 0.53, 1.0);
            let c = Color::new(
                p.ruby.r + (lit.r - p.ruby.r) * glow,
                p.ruby.g + (lit.g - p.ruby.g) * glow,
                p.ruby.b + (lit.b - p.ruby.b) * glow,
                1.0,
            );
            (c, p.ruby)
        } else {
            (
                Color::new(0.1, 0.05, 0.1, 1.0),
                Color::new(0.06, 0.03, 0.06, 1.0),
            )
        };
        draw_rectangle(x, y, PIP, PIP, fade(body, alpha));
        draw_rectangle(x, y, PIP, 1.0, fade(top, alpha));
        draw_rectangle(x, y, 1.0, PIP, fade(top, alpha));
    }
}
